contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address recipient, address sender, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        // record pre-state
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        bool reverted;
        // Make the call from this contract (which is msg.sender for c). To simulate a call from
        // a different sender, we pass 'sender' as a parameter and compare to ownerBefore below.
        // We actually perform the withdrawAll call now, sending no Ether to c.
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = address(c).balance;

        // General property: if this contract was the owner then withdrawAll must not leave the contract's
        // Ether balance increased (it can only decrease or stay equal) and if it succeeded then the
        // contract's balance must have decreased by exactly balanceBefore - balanceAfter.
        // More importantly: if the caller (this contract) is not the owner then either the call reverted
        // or the balance remains unchanged.
        bool iAmOwner = (ownerBefore == address(this));

        // Assert the general rule combining both cases.
        assert(
            // If caller is owner and call did not revert then c's balance decreased by some amount <= balanceBefore
            ((iAmOwner && !reverted) ? (balanceAfter <= balanceBefore) : true)
            &&
            // If caller is not owner then either reverted or balance unchanged
            ((!iAmOwner) ? (reverted || (balanceAfter == balanceBefore)) : true)
        );
    }

    receive() external payable {}
}

